/**
 * @deepseek-ai/dsh-llm 的最小桩。
 *
 * 原注释说"插件仅在注册/适配层引用这些符号，协议路径不调用其逻辑"——
 * 对 Trae / WorkBuddy 成立，**对 Qoder 不成立**：Qoder 的 transport 在 chat 路径上
 * 直接调用 `ProviderRequestId(...)`（把上游的 x-request-id 归一化成品牌 id），
 * 所以这个符号必须是**可调用函数**而不是 `{ create }` 对象。
 *
 * 踩坑记录：写成对象时 Qoder 的 chat 抛 `ProviderRequestId is not a function`，
 * 而且该错误被 transport 的错误包装掩盖成
 * `TypeError: Cannot read properties of undefined (reading 'status')` + 502，极难定位。
 * 改这几个符号前先确认 Qoder 的用法。
 */

/** 请求 id 工厂。DSH 用它做品牌类型，本地返回带前缀的字符串即可。 */
export function ProviderRequestId(value) {
  return `req:${String(value)}`;
}
// 兼容对象式用法（旧桩形态），避免其它调用点回归
ProviderRequestId.create = (value) => ProviderRequestId(value ?? '0');

/** 推理强度 id 工厂 */
export function ReasoningEffortId(value) {
  return String(value);
}
ReasoningEffortId.create = (value) => ReasoningEffortId(value);

/** 工具调用 id 工厂 */
export function ToolCallId(value) {
  return `call:${String(value ?? Math.random().toString(36).slice(2, 10))}`;
}
ToolCallId.create = (value) => ToolCallId(value);

export const EMPTY_RESPONSE_CODE = 'empty_response';

export class LlmError extends Error {}
export function resolveRetryPolicy() { return { retries: 0 }; }
export function attributionHeaders() { return {}; }
export function contentHasImage() { return false; }
/**
 * 消息构造器。**必须补上 role 字段**。
 *
 * 真实实现会做品牌化并保证 `role` 存在；调用点传进来的是
 * `{ content, source }`（**不含 role**），transport 随后靠 `message.role` 分派。
 * 旧桩写成 `return m ?? {role:...}`，只在参数为 undefined 时才补 role，
 * 于是 Qoder 的每条消息都缺 role → 上游回 400
 * "is not one of ['system','assistant','user','tool','function']"。
 */
function withRole(role) {
  return (m) => ({ ...(m ?? {}), role: m?.role ?? role, content: m?.content ?? '' });
}
export const createAssistantMessage = withRole('assistant');
export const createUserMessage = withRole('user');
export const createToolResultMessage = withRole('tool');
export function resolveImageAttachmentAccess() { return { allowed: false }; }
